// Independent reread of archived runs, raw clocks, binaries and generated bytes.
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { hash, manifest, writeJson } from '../gopurs-aff/common.mjs';

const [outArg, ...directories] = process.argv.slice(2);
assert(outArg && directories.length, 'verify.mjs OUTPUT.json CAMPAIGN_DIRECTORY...');
const checks = [];
const median = values => { const xs = values.toSorted((a, b) => a - b), n = xs.length;
  return n % 2 ? xs[n >> 1] : (xs[(n >> 1) - 1] + xs[n >> 1]) / 2; };
for (const path of directories.map(resolvePath => resolve(resolvePath))) {
  const resultPath = join(path, 'results.json');
  const results = JSON.parse(readFileSync(resultPath, 'utf8'));
  assert.equal(results.status, 'passed');
  assert.deepEqual(manifest(join(path, 'compilers')), results.frozen.compilers);
  const original = JSON.parse(readFileSync(join(results.snapshot, 'results.json'), 'utf8'));
  const reference = original.reference_generations.find(r => r.family === 'gopurs');
  const expected = JSON.parse(readFileSync(reference.generated_manifest, 'utf8'));
  for (const item of results.frozen.inputs) assert.equal(hash(readFileSync(join(path, 'inputs', item.path))), item.sha256);
  for (const record of results.runs) {
    assert.equal(record.exit_code, 0);
    const actual = manifest(record.output, file => file.endsWith('.go') || file.endsWith('/go.mod'));
    assert.deepEqual(actual, expected);
    assert.deepEqual(actual, JSON.parse(readFileSync(record.generated_manifest, 'utf8')));
    assert.equal(actual.length, record.identical_files);
    const clocks = Object.fromEntries([...readFileSync(record.stderr, 'utf8').matchAll(/^\[gopurs\] (.+): (\d+) ms$/gm)]
      .map(([, phase, ms]) => [phase, Number(ms)]));
    assert.deepEqual(clocks, record.phases_ms);
  }
  for (const [name, summary] of Object.entries(results.summary)) {
    const runs = results.runs.filter(r => !r.warmup && r.variant === name);
    const samples = runs.map(r => r.phases_ms['backend total']);
    assert.equal(samples.length, results.protocol.rounds);
    assert.deepEqual(samples, summary.samples_ms);
    assert.equal(median(samples), summary.median_ms);
    assert.equal(samples.reduce((a, b) => a + b, 0) / samples.length, summary.mean_ms);
    assert.equal(Math.min(...samples), summary.min_ms);
    assert.equal(Math.max(...samples), summary.max_ms);
    for (const [phase, ms] of Object.entries(summary.phases_median_ms))
      assert.equal(median(runs.map(r => r.phases_ms[phase])), ms);
  }
  checks.push({ directory: path, results_sha256: hash(readFileSync(resultPath)),
    generations: results.runs.length, identical_files: results.runs.reduce((n, r) => n + r.identical_files, 0) });
}
const verification = { status: 'passed', verified_at: new Date().toISOString(), campaigns: checks,
  generations: checks.reduce((n, c) => n + c.generations, 0), identical_files: checks.reduce((n, c) => n + c.identical_files, 0) };
writeJson(resolve(outArg), verification);
console.log(JSON.stringify(verification, null, 2));
